import base64
import os

file_path = 'C:/Users/abdur/Desktop/Fullstack/Fastapi/backend/app/routers/admin.py'
with open(file_path, 'r', encoding='utf-8') as f:
    text = f.read()

# Let's truncate everything after 'class FormatMarkdownRequest'
idx = text.find('class FormatMarkdownRequest')
if idx != -1:
    text = text[:idx]

idx2 = text.find('import google.generativeai as genai')
if idx2 != -1 and idx2 > text.find('def admin_search'):
    text = text[:idx2]

# ensure we only truncate the extra import os at the end
text = text.rstrip()
if text.endswith('import os'):
    text = text[:-9].rstrip()

payload = ""

code_str = base64.b64decode(payload).decode('utf-8')

with open(file_path, 'w', encoding='utf-8') as f:
    f.write(text + '\n\n' + code_str + '\n')

print("DONE")
